/**
 * The contract `form-element.tsx` (native) and `form-element.web.tsx` implement.
 *
 * Its own module because Metro resolves `./form-element` to the `.web.tsx` file
 * on web, so that file cannot import the shared pieces from `./form-element`
 * without importing itself.
 */
import type { ReactNode } from "react";

export type FormElementProps = {
  /** Submits the form. Web wires it to the DOM submit event; native does not. */
  onSubmit: () => void;
  className?: string | undefined;
  children?: ReactNode;
};

/**
 * The element `<Form>` renders on native: a plain `View`.
 *
 * There is no submit event to listen for off web — `SubmitButton` calls
 * `form.handleSubmit()` on press, which is the only path to submission there.
 */
import { View } from "react-native";
import type { FormElementProps } from "@/components/ui/form-element-base";
import { cn } from "@/lib/utils";

export function FormElement({ className, children }: FormElementProps) {
  return <View className={cn("flex-col", className)}>{children}</View>;
}

/**
 * The element `<Form>` renders on web: a real `<form>`.
 *
 * Kept for one reason — Enter inside a field raises the DOM submit event, and
 * nothing else in the tree does. `SubmitButton` is a `Pressable`, not a submit
 * control, so the two paths cannot both fire for one press.
 */
import type { FormElementProps } from "@/components/ui/form-element-base";
import { cn } from "@/lib/utils";

export function FormElement({ onSubmit, className, children }: FormElementProps) {
  return (
    <form
      className={cn("flex flex-col", className)}
      onSubmit={(e) => {
        e.preventDefault();
        e.stopPropagation();
        onSubmit();
      }}
    >
      {children}
    </form>
  );
}
